    max-width: 100%;
    border-radius: 20px 20px 0 0;
    max-height: 95vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
  }
  .funnel-body { padding: 24px 18px 20px; }
  .funnel-title { font-size: 22px; }
  .funnel-sub { font-size: 12.5px; margin-bottom: 18px; }
  .partner-overlay { padding: 0; align-items: flex-end; }
  .partner-modal {
    max-width: 100%;
    border-radius: 20px 20px 0 0;
    max-height: 95vh;
  }
  .partner-form { padding: 0 18px 20px; }
  .partner-modal-header { padding: 24px 18px 0; }
}

/* Item 135 — Internal scroll for long modals */
.portal-overlay > .portal-modal,
.legal-overlay > .legal-modal {
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

/* Item 127 — Fluid layouts (replace fixed breakpoints with clamp) */
.section-h { font-size: clamp(22px, 5vw, 34px); }
.section-p { font-size: clamp(13px, 2.5vw, 15px); }
.wrap { max-width: 1280px; margin: 0 auto; padding: 0 clamp(12px, 3vw, 24px); }
section { padding: clamp(48px, 10vw, 96px) clamp(12px, 3vw, 24px); }

/* Item 142 — Additional reduced motion: disable parallax, ticker, animations */
@media (prefers-reduced-motion: reduce) {
  .ticker-track { animation: none !important; }
  .reveal { opacity: 1 !important; transform: none !important; }
  .phone-glow { animation: none !important; }
  .live-ticker-dot { animation: none !important; }
  * { scroll-behavior: auto !important; }
}

/* Item 141 — Prevent videos/Reels from covering content */
video {
  max-width: 100%;
  height: auto;
  object-fit: contain;
}
.vx-card video {
  background: var(--bg);
  z-index: 1;
}

/* Item 145 — Accessible labels for icon-only buttons */
.nav-reels-btn[aria-label],
.nav-hamburger[aria-label],
.fsoc[aria-label] {
  position: relative;
}

/* Item 147 — Landmarks and heading structure */
[role="navigation"] { nav-up: main; }
main { display: block; }

/* Item 116 — Long-term cache for versioned resources (companion to deploy headers) */
/* The deploy script sets Cache-Control: public, max-age=31536000, immutable for ?v= assets */

